(()=>{const n=document.querySelector("#lesson-catalog");if(!n)return;const r=e=>String(e||"");async function m(){try{const e=await fetch("/api/lessons",{headers:{Accept:"application/json"}});if(!e.ok)throw new Error("The lesson library is not available right now.");const{lessons:c}=await e.json();n.replaceChildren();const o=document.createElement("div");o.className="card-grid lesson-grid",c.forEach(t=>{const a=document.createElement("a");a.className=`content-card lesson-card ${t.access==="premium"?"premium-lesson-card":""}`,a.href=`/lessons/${encodeURIComponent(t.slug)}`;const s=document.createElement("span");s.textContent=`LESSON ${String(t.number).padStart(2,"0")} \xB7 ${t.access==="premium"?"PREMIUM":"FREE"}`;const l=document.createElement("strong");l.textContent=r(t.title);const i=document.createElement("small");i.textContent=r(t.summary),a.append(s,l,i),o.append(a)}),n.append(o)}catch(e){const c=document.createElement("p");c.textContent=e.message,n.replaceChildren(c)}}m()})();
